import glob,re,os
files={}
for f in glob.glob("Chapter */Graph/*.md"): files[os.path.basename(f)[:-3]]=f
adj={k:set() for k in files}; unres=set()
for k,f in files.items():
    for l in re.findall(r"\[\[(.+?)\]\]",open(f,encoding="utf-8").read()):
        if l in files: adj[k].add(l);adj[l].add(k)
        else: unres.add(l)
seen=set();comps=[]
for k in files:
    if k in seen: continue
    st=[k];c=set()
    while st:
        x=st.pop()
        if x in c: continue
        c.add(x);st+=adj[x]
    seen|=c;comps.append(c)
print([len(c) for c in comps],unres)
EOF

